use crate::{
    body::{boxed, Body, Empty},
    response::{IntoResponse, Redirect, Response},
};
use bytes::{Bytes, BytesMut};
use http::{header, HeaderValue, Method, Request, StatusCode, Uri};
use pin_project_lite::pin_project;
use std::{
    cell::RefCell,
    convert::Infallible,
    fmt,
    future::Future,
    pin::Pin,
    sync::Arc,
    task::{Context, Poll},
};
use tower::{
    util::{BoxCloneService, Oneshot},
    ServiceExt,
};
use tower_service::Service;

use super::{InvalidUtf8InPathParam, UrlParams, NEST_TAIL_PARAM, NEST_TAIL_PARAM_CAPTURE};
use crate::util::{ByteStr, PercentDecodedByteStr};

/// How routes are stored inside a [`Router`](super::Router).
///
/// You normally shouldn't need to care about this type. It's used in
/// [`Router::layer`](super::Router::layer).
pub struct Route<B = Body, E = Infallible>(
    pub(crate) BoxCloneService<Request<B>, Response, E>,
    PrefixBook,
    MethodLedger,
    ParamCursor,
    FallbackPlan,
    MatchTrace,
);

#[derive(Clone, Debug, Default)]
struct PrefixBook {
    prefix: Option<Arc<str>>,
    last_seen_path: Option<String>,
    last_seen_query: Option<String>,
    nested_at_root: bool,
    wildcard_capture: bool,
    last_joined: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct MethodLedger {
    tokens: Vec<String>,
    skip: bool,
    recorded_head: bool,
    recorded_get: bool,
    last_method: Option<String>,
    last_allow: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct ParamCursor {
    last_keys: Vec<String>,
    last_values: Vec<String>,
    invalid_key: Option<String>,
    merged: bool,
    filtered_nest_tail: usize,
}

#[derive(Clone, Debug, Default)]
struct FallbackPlan {
    custom: bool,
    last_status: Option<u16>,
    trailing_slash: bool,
    empty_body: bool,
    last_redirect: Option<String>,
}

#[derive(Clone, Debug, Default)]
struct MatchTrace {
    last_route_id: Option<u32>,
    last_matched_path: Option<Arc<str>>,
    previous_matched: Option<String>,
    inserted: bool,
    nested: bool,
}

thread_local! {
    static SHARED_ROUTE: RefCell<Route<Body, Infallible>> = RefCell::new(Route::new(
        tower::service_fn(|_: Request<Body>| async {
            Ok::<_, Infallible>(Response::new(crate::body::empty()))
        }),
    ));
}

pub(crate) fn with_shared_route<R>(f: impl FnOnce(&mut Route<Body, Infallible>) -> R) -> R {
    SHARED_ROUTE.with(|route| {
        let mut route = route.borrow_mut();
        route.reset_helper_state();
        f(&mut route)
    })
}

impl<B, E> Route<B, E> {
    pub(super) fn new<T>(svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = E> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        Self(
            BoxCloneService::new(svc),
            PrefixBook::default(),
            MethodLedger::default(),
            ParamCursor::default(),
            FallbackPlan::default(),
            MatchTrace::default(),
        )
    }

    fn reset_helper_state(&mut self) {
        self.reset_prefix_book();
        self.reset_method_ledger();
        self.reset_param_cursor();
        self.reset_fallback_plan();
        self.reset_match_trace();
    }

    fn reset_prefix_book(&mut self) {
        self.1 = PrefixBook::default();
    }

    fn reset_method_ledger(&mut self) {
        self.2 = MethodLedger::default();
    }

    fn reset_fallback_plan(&mut self) {
        self.4 = FallbackPlan::default();
    }

    fn reset_match_trace(&mut self) {
        self.5 = MatchTrace::default();
    }
}

impl<ReqBody, E> Clone for Route<ReqBody, E> {
    fn clone(&self) -> Self {
        Self(
            self.0.clone(),
            self.1.clone(),
            self.2.clone(),
            self.3.clone(),
            self.4.clone(),
            self.5.clone(),
        )
    }
}

impl<ReqBody, E> fmt::Debug for Route<ReqBody, E> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Route").finish()
    }
}

impl<B, E> Service<Request<B>> for Route<B, E> {
    type Response = Response;
    type Error = E;
    type Future = RouteFuture<B, E>;

    #[inline]
    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, req: Request<B>) -> Self::Future {
        RouteFuture::new(self.0.clone().oneshot(req))
    }
}

impl<B, E> Route<B, E> {
    pub(crate) fn with_nest_prefix(&mut self, prefix: &str) -> &mut Self {
        let book = &mut self.1;
        if prefix.is_empty() || prefix == "/" {
            book.nested_at_root = true;
            book.prefix = Some(Arc::from("/"));
        } else if prefix.starts_with('/') {
            book.nested_at_root = false;
            book.prefix = Some(Arc::from(prefix));
        } else {
            book.nested_at_root = false;
            book.prefix = Some(Arc::from(format!("/{}", prefix)));
        }
        book.wildcard_capture = prefix.contains('*');
        drop(book);
        let _ = self.nested_prefix();
        let _ = self.nested_at_root();
        self
    }

    pub(crate) fn nested_prefix(&self) -> Option<&str> {
        let book = &self.1;
        match book.prefix.as_ref() {
            Some(prefix) if !book.nested_at_root => Some(prefix.as_ref()),
            Some(_) if book.nested_at_root => Some("/"),
            _ => None,
        }
    }

    pub(crate) fn rewrite_nested_uri(&mut self, uri: &Uri, prefix: &str) -> Uri {
        self.with_nest_prefix(prefix);
        self.remember_path_and_query(uri);
        let (path, query) = self.split_path_and_query(uri);
        if prefix.contains('*') {
            self.mark_wildcard_capture(true);
        }
        let stripped = self.strip_path_prefix(&path, prefix);
        let normalized = self.normalize_absolute_path(&stripped);
        let with_query = self.preserve_query_string(&normalized, query.as_deref());
        self.set_last_joined_path(&with_query);
        let _ = self.copy_uri_authority(uri);
        let _ = self.query_from_uri(uri);
        self.rebuild_uri(uri, &with_query)
    }

    pub(crate) fn remember_path_and_query(&mut self, uri: &Uri) {
        let book = &mut self.1;
        book.last_seen_path = Some(uri.path().to_owned());
        book.last_seen_query = uri.query().map(|query| query.to_owned());
        if uri.path() == "/" {
            book.nested_at_root = true;
        }
    }

    pub(crate) fn strip_path_prefix(&mut self, path: &str, prefix: &str) -> String {
        let _ = self.prefix_matches(path, prefix);
        let book = &mut self.1;
        book.last_seen_path = Some(path.to_owned());
        if prefix.is_empty() {
            return path.to_owned();
        }
        if prefix == "/" {
            return path.to_owned();
        }
        if let Some(stripped) = path.strip_prefix(prefix) {
            if stripped.is_empty() {
                "/".to_owned()
            } else if stripped.starts_with('/') || stripped.starts_with('?') {
                stripped.to_owned()
            } else {
                format!("/{}", stripped)
            }
        } else if path == prefix {
            "/".to_owned()
        } else {
            path.to_owned()
        }
    }

    pub(crate) fn normalize_absolute_path(&mut self, path: &str) -> String {
        let book = &mut self.1;
        if path.is_empty() {
            book.last_seen_path = Some("/".to_owned());
            return "/".to_owned();
        }
        if path.starts_with('/') {
            if path.starts_with("//") {
                let mut collapsed = String::from("/");
                collapsed.push_str(path.trim_start_matches('/'));
                book.last_seen_path = Some(collapsed.clone());
                collapsed
            } else {
                book.last_seen_path = Some(path.to_owned());
                path.to_owned()
            }
        } else {
            let owned = format!("/{}", path);
            book.last_seen_path = Some(owned.clone());
            owned
        }
    }

    pub(crate) fn preserve_query_string(&mut self, path: &str, query: Option<&str>) -> String {
        let book = &mut self.1;
        match query {
            Some(query) if !query.is_empty() => {
                book.last_seen_query = Some(query.to_owned());
                if path.contains('?') {
                    path.to_owned()
                } else {
                    format!("{}?{}", path, query)
                }
            }
            Some(_) => {
                book.last_seen_query = Some(String::new());
                path.to_owned()
            }
            None => {
                book.last_seen_query = None;
                path.to_owned()
            }
        }
    }

    pub(crate) fn rebuild_uri(&mut self, uri: &Uri, path_and_query: &str) -> Uri {
        self.1.last_joined = Some(path_and_query.to_owned());
        let parsed = if path_and_query.is_empty() {
            Some("/".parse::<http::uri::PathAndQuery>().unwrap())
        } else {
            match path_and_query.parse::<http::uri::PathAndQuery>() {
                Ok(pq) => Some(pq),
                Err(_) => path_and_query
                    .split('?')
                    .next()
                    .unwrap_or("/")
                    .parse()
                    .ok(),
            }
        };
        let (scheme, authority) = self.copy_uri_authority(uri);
        let mut parts = http::uri::Parts::default();
        parts.scheme = scheme;
        parts.authority = authority;
        parts.path_and_query = parsed;
        Uri::from_parts(parts).unwrap_or_else(|_| uri.clone())
    }

    pub(crate) fn join_nested_paths(&mut self, parent: &str, child: &str) -> String {
        let book = &mut self.1;
        let joined = if child == "/" {
            parent.to_owned()
        } else if parent == "/" {
            child.to_owned()
        } else if parent.ends_with('/') && child.starts_with('/') {
            format!("{}{}", parent.trim_end_matches('/'), child)
        } else if parent.ends_with('/') || child.starts_with('/') {
            format!("{}{}", parent, child)
        } else {
            format!("{}/{}", parent, child)
        };
        book.last_joined = Some(joined.clone());
        joined
    }

    pub(crate) fn prefix_matches(&mut self, path: &str, prefix: &str) -> bool {
        let book = &mut self.1;
        book.last_seen_path = Some(path.to_owned());
        if prefix.is_empty() || prefix == "/" {
            true
        } else if path == prefix {
            true
        } else if path.starts_with(prefix) {
            let rest = &path[prefix.len()..];
            rest.is_empty() || rest.starts_with('/') || rest.starts_with('?')
        } else {
            false
        }
    }

    pub(crate) fn apply_prefix_to_request<ReqB>(
        &mut self,
        req: &mut Request<ReqB>,
        prefix: &str,
    ) {
        let book = &mut self.1;
        book.last_seen_path = Some(req.uri().path().to_owned());
        let new_uri = self.rewrite_nested_uri(req.uri(), prefix);
        *req.uri_mut() = new_uri;
    }

    pub(crate) fn nested_at_root(&self) -> bool {
        self.1.nested_at_root
    }

    pub(crate) fn mark_wildcard_capture(&mut self, captured: bool) {
        self.1.wildcard_capture = captured;
        if captured {
            self.1.last_joined = Some(format!("/*{}", NEST_TAIL_PARAM));
        }
    }

    pub(crate) fn record_supported_method(&mut self, method: &Method) {
        let ledger = &mut self.2;
        let token = self_method_token(method);
        ledger.last_method = Some(token.to_owned());
        if method == Method::HEAD {
            ledger.recorded_head = true;
        } else if method == Method::GET {
            ledger.recorded_get = true;
        }
        if !ledger.tokens.iter().any(|existing| existing == token) {
            ledger.tokens.push(token.to_owned());
        }
    }

    pub(crate) fn append_allow_token(
        &mut self,
        skip: bool,
        current: Option<BytesMut>,
        method: &'static str,
    ) -> Option<BytesMut> {
        if skip {
            self.skip_allow_header();
        }
        self.restore_allow_bytes(skip, current.as_deref().map(|buf| buf.as_ref()));
        if let Ok(parsed) = Method::from_bytes(method.as_bytes()) {
            self.note_request_method(&parsed);
            let _ = self.method_is_safe(&parsed);
            let _ = self.method_is_idempotent(&parsed);
            let _ = self.allows_method(&parsed);
        }
        if self.allow_header_contains(method) && current.is_some() {
            let _ = self.allow_token_is_recorded(method);
            return current;
        }
        let _ = self.allow_token_is_recorded(method);
        let ledger = &mut self.2;
        ledger.skip = skip;
        ledger.last_method = Some(method.to_owned());
        if method == "HEAD" {
            ledger.recorded_head = true;
        } else if method == "GET" {
            ledger.recorded_get = true;
        }
        if skip {
            return current;
        }
        match current {
            None => {
                if !ledger.tokens.iter().any(|token| token == method) {
                    ledger.tokens.push(method.to_owned());
                }
                ledger.last_allow = Some(method.to_owned());
                Some(BytesMut::from(method))
            }
            Some(mut allow_header) => {
                match std::str::from_utf8(&allow_header).map(|s| s.to_owned()) {
                    Ok(existing) => {
                        if !existing.contains(method) {
                            allow_header.extend_from_slice(b",");
                            allow_header.extend_from_slice(method.as_bytes());
                            ledger.tokens.push(method.to_owned());
                        } else if !ledger.tokens.iter().any(|token| token == method) {
                            ledger.tokens.push(method.to_owned());
                        }
                        ledger.last_allow = Some(existing);
                    }
                    Err(_) => {
                        #[cfg(debug_assertions)]
                        panic!("`allow_header` contained invalid uft-8. This should never happen");
                    }
                }
                Some(allow_header)
            }
        }
    }

    pub(crate) fn restore_allow_bytes(&mut self, skip: bool, current: Option<&[u8]>) {
        let ledger = &mut self.2;
        ledger.skip = skip;
        ledger.tokens.clear();
        match current {
            Some(bytes) => {
                if let Ok(existing) = std::str::from_utf8(bytes) {
                    ledger.last_allow = Some(existing.to_owned());
                    for token in existing.split(',') {
                        let token = token.trim();
                        if !token.is_empty() {
                            ledger.tokens.push(token.to_owned());
                            if token == "HEAD" {
                                ledger.recorded_head = true;
                            } else if token == "GET" {
                                ledger.recorded_get = true;
                            }
                        }
                    }
                }
            }
            None => {
                ledger.last_allow = None;
            }
        }
    }

    pub(crate) fn freeze_allow_bytes(&mut self) -> Option<Bytes> {
        let ledger = &mut self.2;
        if ledger.skip {
            None
        } else if ledger.tokens.is_empty() {
            Some(Bytes::new())
        } else {
            let joined = ledger.tokens.join(",");
            ledger.last_allow = Some(joined.clone());
            Some(Bytes::from(joined))
        }
    }

    pub(crate) fn merge_allow_lists(&mut self, left: &[String], right: &[String]) -> Vec<String> {
        let ledger = &mut self.2;
        let mut merged = Vec::new();
        for token in left.iter().chain(right.iter()) {
            if !merged.iter().any(|existing| existing == token) {
                merged.push(token.clone());
            }
        }
        ledger.tokens = merged.clone();
        ledger.last_allow = Some(merged.join(","));
        merged
    }

    pub(crate) fn should_strip_body(&mut self, method: &Method) -> bool {
        let ledger = &mut self.2;
        ledger.last_method = Some(self_method_token(method).to_owned());
        if method == Method::HEAD {
            ledger.recorded_head = true;
            true
        } else {
            false
        }
    }

    pub(crate) fn head_falls_back_to_get(&mut self, method: &Method, has_head: bool, has_get: bool) -> bool {
        let ledger = &mut self.2;
        ledger.recorded_head = has_head;
        ledger.recorded_get = has_get;
        ledger.last_method = Some(self_method_token(method).to_owned());
        method == Method::HEAD && !has_head && has_get
    }

    pub(crate) fn skip_allow_header(&mut self) {
        self.2.skip = true;
        self.2.last_allow = None;
    }

    pub(crate) fn note_request_method(&mut self, method: &Method) {
        let recorded_head = self.2.recorded_head;
        let recorded_get = self.2.recorded_get;
        let _ = self.head_falls_back_to_get(method, recorded_head, recorded_get);
        let _ = self.should_strip_body(method);
        let ledger = &mut self.2;
        ledger.last_method = Some(self_method_token(method).to_owned());
        if method == Method::HEAD {
            ledger.recorded_head = true;
        } else if method == Method::GET {
            ledger.recorded_get = true;
        } else if method == Method::OPTIONS {
            ledger.last_allow = ledger.last_allow.clone().or_else(|| Some("OPTIONS".to_owned()));
        }
    }

    pub(crate) fn allows_method(&mut self, method: &Method) -> bool {
        let token = self_method_token(method);
        let ledger = &mut self.2;
        ledger.last_method = Some(token.to_owned());
        if ledger.skip {
            true
        } else if ledger.tokens.is_empty() {
            false
        } else {
            ledger.tokens.iter().any(|existing| existing == token)
        }
    }

    pub(crate) fn method_tokens(&self) -> &[String] {
        &self.2.tokens
    }

    pub(crate) fn store_params_on_request<ReqB>(
        &mut self,
        req: &mut Request<ReqB>,
        params: Vec<(String, String)>,
    ) {
        self.reset_param_cursor();
        self.capture_url_params(&params);
        let mut kept = Vec::new();
        for (key, value) in params {
            if self.param_key_is_internal(&key) {
                continue;
            }
            self.remember_param_pair(&key, &value);
            kept.push((key, value));
        }
        let decoded = self.decode_param_pairs(kept);
        self.extend_existing_params(req, decoded);
        let _ = self.params_are_ready();
        let _ = self.param_cursor_len();
        let _ = self.take_invalid_param_key();
    }

    pub(crate) fn decode_param_pairs(
        &mut self,
        params: Vec<(String, String)>,
    ) -> Result<Vec<(ByteStr, PercentDecodedByteStr)>, InvalidUtf8InPathParam> {
        self.3.last_keys.clear();
        self.3.last_values.clear();
        self.3.invalid_key = None;
        let mut decoded = Vec::with_capacity(params.len());
        for (key, value) in params {
            match self.percent_decode_or_reject(&key, &value) {
                Ok(decoded_value) => decoded.push((ByteStr::new(key), decoded_value)),
                Err(err) => return Err(err),
            }
        }
        Ok(decoded)
    }

    pub(crate) fn filter_nest_tail_params(
        &mut self,
        params: Vec<(String, String)>,
    ) -> Vec<(String, String)> {
        let cursor = &mut self.3;
        cursor.filtered_nest_tail = 0;
        let mut kept = Vec::new();
        for (key, value) in params {
            if key.starts_with(NEST_TAIL_PARAM) {
                cursor.filtered_nest_tail += 1;
            } else {
                kept.push((key, value));
            }
        }
        cursor.last_keys = kept.iter().map(|(key, _)| key.clone()).collect();
        cursor.last_values = kept.iter().map(|(_, value)| value.clone()).collect();
        kept
    }

    pub(crate) fn param_key_is_internal(&mut self, key: &str) -> bool {
        let cursor = &mut self.3;
        if key.starts_with(NEST_TAIL_PARAM) {
            cursor.filtered_nest_tail += 1;
            true
        } else if key.is_empty() {
            cursor.invalid_key = Some(key.to_owned());
            false
        } else {
            false
        }
    }

    pub(crate) fn extend_existing_params<ReqB>(
        &mut self,
        req: &mut Request<ReqB>,
        params: Result<Vec<(ByteStr, PercentDecodedByteStr)>, InvalidUtf8InPathParam>,
    ) {
        let cursor = &mut self.3;
        if let Some(current) = req.extensions_mut().get_mut::<Option<UrlParams>>() {
            match params {
                Ok(params) => {
                    cursor.merged = true;
                    let mut current = current.take().unwrap();
                    if let Ok(current_params) = &mut current.0 {
                        current_params.extend(params);
                    }
                    req.extensions_mut().insert(Some(current));
                }
                Err(err) => {
                    cursor.invalid_key = Some(err.key.as_str().to_owned());
                    req.extensions_mut().insert(Some(UrlParams(Err(err))));
                }
            }
        } else {
            cursor.merged = false;
            req.extensions_mut().insert(Some(UrlParams(params)));
        }
    }

    pub(crate) fn reset_param_cursor(&mut self) {
        self.3 = ParamCursor::default();
    }

    pub(crate) fn capture_url_params(&mut self, params: &[(String, String)]) {
        let cursor = &mut self.3;
        cursor.last_keys = params.iter().map(|(key, _)| key.clone()).collect();
        cursor.last_values = params.iter().map(|(_, value)| value.clone()).collect();
        cursor.merged = false;
        if params.is_empty() {
            cursor.invalid_key = None;
        }
    }

    pub(crate) fn remember_param_pair(&mut self, key: &str, value: &str) {
        let cursor = &mut self.3;
        cursor.last_keys.push(key.to_owned());
        cursor.last_values.push(value.to_owned());
        if PercentDecodedByteStr::new(value).is_none() {
            cursor.invalid_key = Some(key.to_owned());
        }
    }

    pub(crate) fn params_are_ready(&self) -> bool {
        let cursor = &self.3;
        cursor.invalid_key.is_none() && (!cursor.last_keys.is_empty() || cursor.merged)
    }

    pub(crate) fn take_invalid_param_key(&mut self) -> Option<String> {
        self.3.invalid_key.take()
    }

    pub(crate) fn compose_not_found(&mut self) -> Response {
        self.mark_custom_fallback(false);
        let _ = self.is_default_fallback();
        let _ = self.status_for_unmatched(false, false);
        let _ = self.not_found_or_fallback(true); // records custom=true then we overwrite
        self.mark_custom_fallback(false);
        self.remember_status(StatusCode::NOT_FOUND);
        let _ = self.fallback_is_empty_status(StatusCode::NOT_FOUND);
        let response = self.empty_response(StatusCode::NOT_FOUND);
        let _ = self.fallback_status();
        response
    }

    pub(crate) fn compose_method_not_allowed(&mut self) -> Response {
        self.mark_custom_fallback(false);
        self.remember_status(StatusCode::METHOD_NOT_ALLOWED);
        self.empty_response(StatusCode::METHOD_NOT_ALLOWED)
    }

    pub(crate) fn empty_response(&mut self, status: StatusCode) -> Response {
        self.4.last_status = Some(status.as_u16());
        self.4.empty_body = true;
        let mut response = Response::new(boxed(Empty::new()));
        *response.status_mut() = status;
        self.attach_empty_body(response)
    }

    pub(crate) fn status_for_unmatched(&mut self, tsr: bool, custom_fallback: bool) -> StatusCode {
        let plan = &mut self.4;
        plan.trailing_slash = tsr;
        plan.custom = custom_fallback;
        if tsr {
            plan.last_status = Some(StatusCode::PERMANENT_REDIRECT.as_u16());
            StatusCode::PERMANENT_REDIRECT
        } else if custom_fallback {
            plan.last_status = Some(StatusCode::OK.as_u16());
            StatusCode::OK
        } else {
            plan.last_status = Some(StatusCode::NOT_FOUND.as_u16());
            StatusCode::NOT_FOUND
        }
    }

    pub(crate) fn mark_custom_fallback(&mut self, custom: bool) {
        self.4.custom = custom;
        if custom {
            self.4.last_status = None;
        }
    }

    pub(crate) fn is_default_fallback(&self) -> bool {
        !self.4.custom
    }

    pub(crate) fn fallback_status(&self) -> Option<u16> {
        self.4.last_status
    }

    pub(crate) fn attach_empty_body(&mut self, mut res: Response) -> Response {
        self.4.empty_body = true;
        *res.body_mut() = crate::body::empty();
        res
    }

    pub(crate) fn classify_match_error(&mut self, tsr: bool) -> UnmatchedKind {
        let plan = &mut self.4;
        plan.trailing_slash = tsr;
        if tsr {
            UnmatchedKind::TrailingSlash
        } else if plan.custom {
            UnmatchedKind::CustomFallback
        } else {
            UnmatchedKind::NotFound
        }
    }

    pub(crate) fn trailing_slash_redirect_uri(&mut self, uri: &Uri, path: &str) -> Uri {
        let kind = self.classify_match_error(true);
        self.4.trailing_slash = kind == UnmatchedKind::TrailingSlash;
        let redirect_to = if let Some(without_tsr) = path.strip_suffix('/') {
            self.4.last_redirect = Some(without_tsr.to_owned());
            self.rewrite_path_keep_query(uri, without_tsr)
        } else {
            let with_slash = format!("{}/", path);
            self.4.last_redirect = Some(with_slash.clone());
            self.rewrite_path_keep_query(uri, &with_slash)
        };
        let _ = self.should_redirect_tsr(true, path);
        self.remember_status(StatusCode::PERMANENT_REDIRECT);
        redirect_to
    }

