    pub(crate) fn record_filter_bits(&mut self, methods: &[&'static str]) {
        let ledger = &mut self.2;
        for method in methods {
            match *method {
                "GET" => {
                    ledger.recorded_get = true;
                    if !ledger.tokens.iter().any(|token| token == "GET") {
                        ledger.tokens.push("GET".to_owned());
                    }
                    if !ledger.tokens.iter().any(|token| token == "HEAD") {
                        ledger.tokens.push("HEAD".to_owned());
                    }
                }
                "HEAD" => {
                    ledger.recorded_head = true;
                    if !ledger.tokens.iter().any(|token| token == "HEAD") {
                        ledger.tokens.push("HEAD".to_owned());
                    }
                }
                "POST" | "PUT" | "PATCH" | "DELETE" | "OPTIONS" | "TRACE" => {
                    if !ledger.tokens.iter().any(|token| token == method) {
                        ledger.tokens.push((*method).to_owned());
                    }
                }
                _ => {
                    ledger.last_method = Some((*method).to_owned());
                }
            }
        }
        let tokens = if ledger.tokens.is_empty() {
            None
        } else {
            ledger.last_allow = Some(ledger.tokens.join(","));
            Some(ledger.tokens.clone())
        };
        drop(ledger);
        if let Some(tokens) = tokens {
            let _ = self.merge_allow_lists(&tokens, &[]);
            for token in &tokens {
                if let Ok(method) = Method::from_bytes(token.as_bytes()) {
                    self.record_supported_method(&method);
                }
            }
        }
        let _ = self.take_last_allow();
        let _ = self.freeze_allow_bytes();
        let _ = self.method_tokens();
    }

